"5.3":{"n":"Суурин газрын эхлэл","d":"суурин газрын доторх хөдөлгөөний журмыг мөрдөх шаардлагатай суурин газрын эхлэл болон нэрийг мэдээлнэ"},
"5.4":{"n":"Суурин газрын төгсгөл","d":"5.3 тэмдэг бүхий нутаг дэвсгэрээс гарч байгааг мэдээлнэ"},
"5.5":{"n":"Суурин газрын эхлэл","d":"суурин газрын доторх хөдөлгөөний журмыг тухайн замд мөрдөх шаардлагагүй суурин газрын эхлэл болон нэрийг мэдээлнэ","r":"5.5, 5.6, 5.37, 5.38.а, 5.38.б тэмдэг нь тууш замд байрласан бол ногоон, бусад замд байрласан бол цэнхэр өнгийн дэвсгэртэй байна."},
"5.6":{"n":"Суурин газрын төгсгөл","d":"5.5 тэмдэг бүхий нутаг дэвсгэрээс гарч байгааг мэдээлнэ","r":"5.5, 5.6, 5.37, 5.38.а, 5.38.б тэмдэг нь тууш замд байрласан бол ногоон, бусад замд байрласан бол цэнхэр өнгийн дэвсгэртэй байна."},
"5.7":{"n":"Нэг чигийн хөдөлгөөн","d":"хөдөлгөөн нь нэг чигт зохион байгуулагдсан зам буюу зорчих хэсэг"},
