"5.9.а":{"n":"Зүүнээс баруун гар тийш нэг чигийн хөдөлгөөнтэй","d":"хөндлөн нийлсэн зам буюу зорчих хэсэг баруун гар тийш нэг чигийн хөдөлгөөнтэй"},
"5.9.б":{"n":"Баруунаас зүүн гар тийш нэг чигийн хөдөлгөөнтэй","d":"хөндлөн нийлсэн зам буюу зорчих хэсэг зүүн гар тийш нэг чигийн хөдөлгөөнтэй"},
"5.10.а":{"n":"Эгнээнээс явах хөдөлгөөний чиг","d":"хөдөлгөөний тухайн чиг дэх эгнээний тоог мэдээлж, эгнээ тус бүрээс тухайн уулзвараар нэвтрэх зөвшөөрсөн чигийг заана. Тэмдгийн зүүн гар тийш эргэхийг зөвшөөрсөн сум бүхий хамгийн зүүн гар талын захын эгнээнээс буцаж эргэхийг зөвшөөрнө","r":"5.10.а тэмдэгт зөвхөн хоёр буюу гурван эгнээний хөдөлгөөний чигийг заана. Харин 5.11.а, 5.11.б тэмдэгт хоёр буюу мөн гурваас олон эгнээний хөдөлгөөний чигийг заасан байж болно."},
"5.10.б":{"n":"Эгнээнээс явах хөдөлгөөний чиг","d":"хөдөлгөөний тухайн чиг дэх эгнээний тоог мэдээлж, эгнээ тус бүрээс тухайн уулзвараар нэвтрэх зөвшөөрсөн чигийг заана. Тэмдгийн зүүн гар тийш эргэхийг зөвшөөрсөн сум бүхий хамгийн зүүн гар талын захын эгнээнээс буцаж эргэхийг зөвшөөрнө"},
"5.11.а":{"n":"Эгнээгээр явах хөдөлгөөний чиг","d":"тухайн зорчих хэсгийн эгнээний тоог болон эгнээ тус бүрийн хөдөлгөөний урсгалын чигийг мэдээлнэ. Тэмдэгт аль нэг тээврийн хэрэгслийн хөдөлгөөнийг хориглосон тэмдэг дүрсэлсэн байвал тухайн эгнээгээр уг тээврийн хэрэгслийн хөдөлгөөнийг хориглоно"},
"5.11.б":{"n":"Эгнээгээр явах хөдөлгөөний чиг","d":"тухайн зорчих хэсгийн эгнээний тоог болон эгнээ тус бүрийн хөдөлгөөний урсгалын чигийг мэдээлнэ. Тэмдэгт аль нэг тээврийн хэрэгслийн хөдөлгөөнийг хориглосон тэмдэг дүрсэлсэн байвал тухайн эгнээгээр уг тээврийн хэрэгслийн хөдөлгөөнийг хориглоно"},
"5.12.а":{"n":"Эгнээний эхлэл","d":"хөдөлгөөний тухайн чигт эгнээний тоо нэмэгдэж байгааг мэдээлнэ. 5.12.а тэмдэгт 4.6 «Хурдны доод хязгаарлал» тэмдгийг дүрсэлсэн байвал уг тэмдэгт зааснаас илүү хурдтай явах боломжгүй тээврийн хэрэгслийн жолооч хөдөлгөөнөө зөвхөн нэмэгдэж буй эгнээгээр үргэлжлүүлнэ. 5.12.б тэмдэгт аль нэг тээврийн хэрэгслийн хөдөлгөөнийг хориглосон тэмдэг дүрсэлсэн байвал тухайн эгнээгээр уг тээврийн хэрэгслийн хөдөлгөөнийг хориглоно"},
"5.12.б":{"n":"Эгнээний эхлэл","d":"хөдөлгөөний тухайн чигт эгнээний тоо нэмэгдэж байгааг мэдээлнэ. 5.12.а тэмдэгт 4.6 «Хурдны доод хязгаарлал» тэмдгийг дүрсэлсэн байвал уг тэмдэгт зааснаас илүү хурдтай явах боломжгүй тээврийн хэрэгслийн жолооч хөдөлгөөнөө зөвхөн нэмэгдэж буй эгнээгээр үргэлжлүүлнэ. 5.12.б тэмдэгт аль нэг тээврийн хэрэгслийн хөдөлгөөнийг хориглосон тэмдэг дүрсэлсэн байвал тухайн эгнээгээр уг тээврийн хэрэгслийн хөдөлгөөнийг хориглоно"},
"5.13.а":{"n":"Эгнээний төгсгөл","d":"хөдөлгөөний тухайн чиг дэх эгнээний тоо хасагдаж байгааг мэдээлнэ"},
"5.13.б":{"n":"Эгнээний төгсгөл","d":"хөдөлгөөний тухайн чиг дэх эгнээний тоо хасагдаж байгааг мэдээлнэ"},
"5.14":{"n":"Чиглэлийн тээврийн хэрэгслийн эгнээ","d":"чиглэлийн тээврийн хэрэгслийн хөдөлгөөнд зориулсан эгнээг мэдээлнэ. Тэмдгийг тухайн эгнээний харалдаа зорчих хэсгийн дээр байрлуулна"},
"5.15":{"n":"Хөдөлгөөний бүдүүвч","d":"хөдөлгөөн нь аль нэг чигт хориглогдсон уулзвараар нэвтэрч гарахад тохиромжтой чиглэл буюу тухайн уулзвар дээрх хөдөлгөөний зохион байгуулалтын онцлогийг мэдээлнэ"},
"5.16":{"n":"Буцаж эргэх газар","d":"тээврийн хэрэгсэл буцаж эргэхэд зориулсан газрыг мэдээлэх бөгөөд зүүн гар тийш эргэхийг хориглоно"},
"5.17":{"n":"Зогсоол","d":"тээврийн хэрэгсэл удаан зогсоход зориулсан газрыг мэдээлнэ. Явган хүний зам дагуух зогсоолыг мэдээлж буй 5.17 тэмдгийн үйлчлэх хүрээ нь байрласан газраасаа эхний түр буюу удаан зогсох хориотой замын хэсэг хүртэл хүчинтэй байна. Үйлчлэх хүрээг 7.2.а нэмэлт тэмдгээр хязгаарлаж болно","r":"5.17 тэмдгээс бусад тэмдгийг хоёроос олон нэмэлт тэмдэгтэй хамт байрлуулахгүй.-ooOoo-"},
"5.18":{"n":"Хурд сааруулагч","d":"тээврийн хэрэгслийн хурдыг сааруулах зориулалт бүхий хиймэл бартааг мэдээлнэ. Замын тухайн хэсэгт хэд хэдэн хурд сааруулагчийг хооронд нь 100 м - ээс холгүй зайтай цувруулан тавьсан бол 7.2.а нэмэлт тэмдгээр тухайн хэсгийн үргэлжлэх зайг заана"},
"5.19.а":{"n":"Явган хүний гарц","d":"зорчих хэсгээр явган зорчигч хөндлөн гарах газрыг мэдээлнэ. Явган хүний гарц нь тэмдэглэлгүй бол 5.19.б тэмдгийг замын баруун гар талд гарцын шууд өмнө, 5.19.а тэмдгийг замын зүүн гар талд гарцын цаана байрлуулна"},
"5.19.б":{"n":"Явган хүний гарц","d":"зорчих хэсгээр явган зорчигч хөндлөн гарах газрыг мэдээлнэ. Явган хүний гарц нь тэмдэглэлгүй бол 5.19.б тэмдгийг замын баруун гар талд гарцын шууд өмнө, 5.19.а тэмдгийг замын зүүн гар талд гарцын цаана байрлуулна"},
